import 'package:flutter/material.dart';
import '../diary/meal_repository.dart';
import 'statistics.dart';
class StatisticsScreen extends StatefulWidget { const StatisticsScreen({super.key,required this.repository}); final MealRepository repository; @override State<StatisticsScreen> createState()=>_StatisticsScreenState(); }
class _StatisticsScreenState extends State<StatisticsScreen>{ bool loading=true; NutritionStatistics stats=const NutritionStatistics([]); int days=0; @override void initState(){super.initState();_load();} Future<void> _load()async{final meals=await widget.repository.load();if(mounted)setState(() { stats = NutritionStatistics(meals); days = groupByDay(meals).length; loading = false; });} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Statistik')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[_card(c,'Kalorien','${stats.kcal.round()} kcal'),_card(c,'Protein','${stats.proteinGrams.round()} g'),_card(c,'Erfasste Tage','$days') ]); Widget _card(BuildContext c,String title,String value)=>Card(child:ListTile(title:Text(title),trailing:Text(value,style:Theme.of(c).textTheme.titleLarge)));}
